insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('de-fleedamaus-is-des-aanzige-seigetia-des-fliang-kau-und-des-mit-ultraschoi', 'De Fleedamaus is des aanzige Seigetia, des fliang kau - und des mit Ultraschoi!', '', '', '', 'Viecher und Tiernamen auf Wienerisch', 'Die Fledermaus ist das einzige Säugetier, das fliegen kann - und das mit Ultraschall!', '[{"kategorie": "wörtlich", "text": "\"Fledermäuse sind die einzigen Säugetiere, die fliegen können - und das mit Ultraschall!\"  2. Fledermäuse sind die einzigen flugfähigen Säugetiere – und nutzen dabei Echoortung!  3. Unter den Säugetieren sind Fledermäuse die einzigen, die fliegen können – und das per Ultraschall-Navigation!\""}]'::jsonb, ''),
  ('glicklich-ist-wea-vagissd-wos-doch-nicht-zu-aendan-ist-a-unschdeablichs-zitat-aus-da-fleedamaus', 'Glicklich ist, wea vagissd, wos doch nicht zu ändan ist - a unschdeablichs Zitat aus da Fleedamaus!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', '‚Glücklich ist, wer vergisst, was doch nicht zu ändern ist‘ – ein unsterbliches Zitat aus der Fledermaus!', '[{"kategorie": "wörtlich", "text": "\"‚Glücklich ist, wer vergisst, was doch nicht zu ändern ist‘ – ein unsterbliches Zitat aus der Fledermaus, frei übersetzt: \"Wer das Unveränderliche akzeptiert, lebt leichter!\"  2. ‚Glücklich ist, wer vergisst, was doch nicht zu ändern ist‘ – ein unsterbliches Zitat aus der Fledermaus, frei übersetzt: \"Was vorbei ist, ist vorbei – wer das kapiert, hat''s leichter im Leben!\"  3.  ‚Glücklich ist, wer vergisst, was doch nicht zu ändern ist‘ – ein unsterbliches Zitat aus der Fledermaus, frei übersetzt: \"Glück beginnt dort, wo der Widerstand gegen das Unvermeidliche endet!\""}]'::jsonb, ''),
  ('es-rostbraadl-schneidst-ausn-hoochn-beiriad-knopp-hintan-gnack-entlaung-da-sechstn-bis-neintn-rippn', 'Es Rostbraadl schneidst ausn hoochn Beiriad, knopp hintan Gnack, entlaung da sechstn bis neintn Rippn!', '', '', '', 'Wiener Fleischhauer-Slang', 'Den Rostbraten schneidest du aus dem hohen Beiried, knapp hinterm Nacken, entlang der sechsten bis neunten Rippe!', '[{"kategorie": "wörtlich, Fleischhauerjargon", "text": "\"Der Rostbraten wird aus der Hochrippe geschnitten – genauer gesagt aus dem Bereich der sechsten bis neunten Rippe, direkt hinter dem Nacken!\"  2. Das Rostbratenstück stammt aus dem Hohen Beiried, zwischen Hals und Lende – Rippen sechs bis neun!  3. Anatomisch gesehen schneidest du den Rostbraten aus dem Rückenstück im Bereich der mittleren Hochrippe, hinter dem Nackenansatz, Rippen sechs bis neun!"}]'::jsonb, 'Hoochs Beiriad'),
  ('fias-rostbraadl-neema-imma-a-schee-ooghaunganes-schdickl-vom-hoochn-beiriad-schmeckd-aafoch-aum-bestn', 'Fias Rostbraadl neema imma a schee ooghaunganes Schdickl vom hoochn Beiriad - schmeckd aafoch aum bestn!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Für den Rostbraten nehmen wir immer ein schön abgehangenes Stückl vom hohen Beiried – schmeckt einfach am besten!', '[{"kategorie": "wörtlich", "text": "\"Der Rostbraten wird bei uns ausschließlich aus gut abgehangenem Hochrippenfleisch geschnitten – den Unterschied schmeckt man!\"  2. Für den Rostbraten nehmen wir nur schön gereifte Hochrippe – das sorgt für Zartheit und Aroma!  3. Rostbraten machen wir nur mit richtig gut gereiftem Fleisch – sonst schmeckt’s nicht wie’s soll!"}]'::jsonb, ''),
  ('beim-vanillirostbroodn-wiads-rindfleisch-zeaschd-schoaf-aubroodn-und-daunn-mit-knoofae-in-da-braadlfettn-dinst', 'Beim Vanillirostbroodn wiads Rindfleisch zeaschd schoaf aubroodn und daunn mit Knoofä in da Braadlfettn dinst!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Beim Vanillerostbraten wird das Rindfleisch zuerst scharf angebraten und dann mit Knoblauch im Bratenfett gedünstet!', '[{"kategorie": "wörtlich", "text": "\"Beim Vanillerostbraten wird das Rindfleisch zuerst scharf angebraten und dann mit Knoblauch und Bratensaft geschmort!\"  2. Das Fleisch für den Vanillerostbraten wird zunächst heiß angebraten, danach mit Knoblauch verfeinert und in Bratensaft gegart!  3. Beim klassischen Wiener Vanillerostbraten brät man das Rindfleisch scharf an und lässt es in aromatischem Bratensaft mit Knoblauch weichschmoren!"}]'::jsonb, ''),
  ('vanilli-ghead-zu-d-oachiaeaen-kummd-uaschbruenglich-aus-mexiko-und-brauchd-a-feichtwoams-klima-mit-hoibschottn', 'Vanilli ghead zu d''Oachiään, kummd uaschbrünglich aus Mexiko und brauchd a feichtwoams Klima mit Hoibschottn!', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Vanille gehört zu den Orchideengewächsen, stammt kommt aus Mexiko und braucht ein feuchtwarmes Klima mit Halbschatten!', '[{"kategorie": "wörtlich", "text": "\"Die echte Vanille gehört zur Familie der Orchideengewächse, stammt ursprünglich aus Mexiko und braucht ein feuchtwarmes Klima mit Halbschatten!\" =  2. (wörtlich): \"Vanilla planifolia gehört zu den Orchideen und benötigt ein tropisches Klima mit hoher Luftfeuchtigkeit und lichtdurchflutetem Halbschatten!\"  3. Die Vanillepflanze ist eine tropische Orchidee aus Mexiko und gedeiht bevorzugt in feuchtwarmen Regionen mit teilweiser Beschattung!"}]'::jsonb, ''),
  ('a-bissal-vanilli-schood-nie-hod-de-omi-imma-gsoogd-waunns-mit-knoofae-kochd-hod', 'A bissal Vanilli schood nie - hod de Omi imma gsoogd, waunns mit Knoofä kochd hod!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'A bisserl Vanilli schadet nie – hat Oma immer gesagt, wenn sie mit Knoblauch gekocht hat!', '[{"kategorie": "wörtlich", "text": "\"Omas Küchenweisheit lautete: Vanilli, der Knoblauch des kleinen Mannes, gehört einfach dazu!\"  2. Schon Oma meinte: Ein wenig ‚Vanilli‘ – also Knoblauch – macht jedes Gericht besser!  3. Bei uns daheim war Knoblauch immer Vanilli – und Oma hat nie damit gespart!"}]'::jsonb, ''),
  ('greesde-zwiifaen', 'greesde Zwiifän', 'die', '', '', 'Wiener Küche & Gaumenfreuden', 'geröstete Zwiebeln', '[{"kategorie": "wörtlich, Pluralform", "text": "\"geröstete Zwiebel\" (in Fett angebratene, klein gehackte Zwiebelstücke, die durch Erhitzen goldbraun bis dunkelbraun karamellisieren und dadurch ein kräftiges, süßlich-herzhaftes Röstaroma entwickeln)"}, {"kategorie": "", "text": "\"Röstzwiebel\", \"goldbraun gebratene Zwiebeln\", \"Zwiebelröster\""}]'::jsonb, ''),
  ('a-zwiifaerostbroodn-wiad-aus-an-schee-mamoriadn-schdickl-vom-hoochn-beiriad-gmochd-und-mit-greesde-zwiifaen-broodeadaepfaen-und-an-elegant-eigschniidanan-faechaguakal-seaviad', 'A Zwiifärostbroodn wiad aus an schee mamoriadn Schdickl vom hoochn Beiriad gmochd und mit greesde Zwiifän, Broodeadäpfän und an elegant eigschniidanan Fächaguakal seaviad!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Ein Wiener Zwiebelrostbraten wird aus einem schön marmorierten Stück vom Hohen Beiried zubereitet und mit knusprigen Röstzwiebeln, Braterdäpfeln und einem elegant eingeschnittenen Fächergurkerl serviert!', '[{"kategorie": "wörtlich", "text": "\"Der Wiener Zwiebelrostbraten wird aus einem schön marmorierten Stück Hochrippe zubereitet und mit knusprigen Röstzwiebeln, Bratkartoffeln und einer elegant eingeschnittenen Fächergurke serviert!\"  2. Für den Wiener Zwiebelrostbraten wird ein gut marmoriertes Stück aus der Hohen Beiried verwendet, das mit Röstzwiebeln, Bratkartoffeln und Fächergurke angerichtet wird!  3. Der Wiener Zwiebelrostbraten - fein durchzogenes Rindfleisch, saftig gebraten, begleitet von gerösteten Zwiebeln, goldenen Bratkartoffeln und einer elegant eingeschnittenen Fächergurke!"}]'::jsonb, 'greesde Zwiifän'),
  ('hoochs-beiriad', 'Hoochs Beiriad', 'das', '', '', 'Wiener Fleischhauer-Slang', 'Hohes Beiried', '[{"kategorie": "wörtlich", "text": "\"hohes Beiried\" (\"Schnittstück beim hohen Ried\" [=\"vorderes Ried\"=\"vorderer Rinderrücken\"]"}, {"kategorie": "Fleischhauerjargon", "text": "\"Hochrippe\" ( Teilstück aus dem vorderen Rinderrücken, zwischen Hals [Kamm] und dem hinteren Rücken), \"Rostbratenstück\", \"Zwischenrippenstück\""}]'::jsonb, ''),
  ('so-lacklhoft-wia-dea-daheareed-passda-ned-wiaklich-zua-feinan-tischgsoeoeschoft', 'So lacklhoft wia dea daheareed, passda ned wiaklich zua feinan Tischgsööschoft!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'So lackelhaft wie der daherredet, passt er nicht wirklich zur feinen Tischgesellschaft!', '[{"kategorie": "wörtlich", "text": "\"So grobschlächtig wie der daherredet, passt er nicht wirklich zur feinen Tischgesellschaft!\"  2. Mit seiner derben Ausdrucksweise wirkt er in so einem feinen Kreis einfach  fehl am Platz!   3. So wie der lospoltert, gehört er eher in die Kantine als an die Festtafel!"}]'::jsonb, ''),
  ('sei-lacklhofte-schdadua-soogd-scho-ollas-iwa-eam-a-groobmotoorika-easchda-klass', 'Sei lacklhofte Schdadua soogd scho ollas iwa eam - a Groobmotoorika easchda Klass!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Seine lackelhafte Statur sagt schon alles über ihn - ein Grobmotoriker erster Klasse!', '[{"kategorie": "wörtlich", "text": "\"Seine massige, ungelenke Erscheinung spricht Bände – ein Grobmotoriker erster Klasse!\"  2. Sein schwerfälliger Körperbau lässt erahnen, dass Feingefühl nicht unbedingt zu seinen Kernkompetenzen zählt!  3. Sein Auftreten erinnert an einen Möbelpacker im Porzellanladen – groß, laut und garantiert nicht zartfühlend!"}]'::jsonb, ''),
  ('waunn-dea-lackl-duachs-buero-schdaumpfd-woogln-de-glaasln-in-da-kredenz', 'Waunn dea Lackl duachs Büro schdaumpfd, woogln de Glaasln in da Kredenz!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wenn dieser Lackel durchs Büro stampft, wackeln die Gläser in der Kredenz!', '[{"kategorie": "wörtlich", "text": "\"Wenn dieser große, ungelenke Kerl durchs Büro stapft, vibriert der Boden und die Gläser scheppern in der Vitrine!\"  2. Wenn dieser Schrank auf zwei Beinen durchs Büro marschiert, denkt man, es ist ein Erdbeben!  3. Der stampft durchs Büro wie ein Elefant im Porzellanladen – da wackelt das ganze Mobiliar und die Gläser klirren!"}]'::jsonb, ''),
  ('so-a-lackl-brauchd-hoid-a-schdoake-frau-de-eam-zeigd-wo-da-haumma-haengd', 'So a Lackl brauchd hoid a schdoake Frau, de eam zeigd, wo da Haumma hängd!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'So ein Lackl braucht halt a starke Frau, die ihm zeigt, wo der Hammer hängt!', '[{"kategorie": "wörtlich", "text": "\"So ein grober, ungehobelter Bursche braucht halt eine starke Frau, die ihm zeigt, wo der Hammer hängt!\"  2. Dieser freche Rüpel braucht eine Frau, die ihn in die Schranken weist!  3. Dieses grobschlächtige Raubein braucht keine Prinzessin – sondern eine Amazone mit Schuhgröße 43!"}]'::jsonb, ''),
  ('so-a-botznlackl-und-trotzdem-gschaamig-wiara-voiksschueuela-des-glaubsd-ned', 'So a Botznlackl und trotzdem gschaamig wiara Voiksschüüla - des glaubsd ned!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'So ein Batzenlackl und trotzdem schamhaft wie ein Volksschüler - das glaubst du nicht!', '[{"kategorie": "wörtlich", "text": "\"So ein Batzenlackl und trotzdem schüchtern wie ein Volksschüler - nicht zu glauben!\"  2. So ein Schrank von einem Mann und trotzdem rot im Gesicht wie ein Erstklässler – unglaublich!  3. Ein echter Klotz von einem Mann, aber schüchtern wie ein Küken – wie passt das zusammen?"}]'::jsonb, ''),
  ('mei-omi-hod-imma-gsoogd-a-moadslackl-bringda-nix-waunna-nix-schnoind', 'Mei Omi hod imma gsoogd: ''A Moadslackl bringda nix, waunna nix schnoind!''', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Meine Oma hat immer gesagt: ''Ein Mordslackel bringt dir nichts, wenn er nichts schnallt!', '[{"kategorie": "wörtlich", "text": "\"Meine Großmutter pflegte zu sagen: ''Ein Riesenkerl nützt dir nichts, wenn er nur ein Mini-Hirn hat''!\"  2. Wie meine Oma immer gesagt hat: Was bringt dir ein Ochs von einem Mann, wenn er nicht einmal Hausverstand hat?  3. Die Oma hat recht: Ein Mordstrumm von Mann – aber wenn oben nix rennt, hilft dir das ganze G’rüst nix!"}]'::jsonb, ''),
  ('waunn-so-a-kraftlackl-in-da-tia-schdeed-traut-si-kaana-oone-ausweis-eine', 'Waunn so a Kraftlackl in da Tia schdeed, traut si kaana oone Ausweis eine!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wenn so ein Kraftlackl in der Tür steht, traut sich keiner ohne Ausweis rein!', '[{"kategorie": "wörtlich", "text": "\"Wenn so ein Muskelprotz am Eingang steht, hat keiner den Mut, ohne Ausweis reinzugehen!\"  2. Bei so einem Schrank von Türsteher traut sich keiner rein, der keinen Ausweis hat!  3. Wenn ein wandelnder Kleiderschrank die Tür bewacht, zückt jeder freiwillig den Ausweis!"}]'::jsonb, ''),
  ('dea-bauanlackl-hod-an-schaeaedl-wiara-amboss-und-haend-wia-baggaschaufaen', 'Dea Bauanlackl hod an Schäädl wiara Amboss und Händ wia Baggaschaufän!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Dieser Bauernlackl hat einen Schädel wie ein Amboss und Hände wie Baggerschaufeln!', '[{"kategorie": "wörtlich", "text": "\"Dieser Bauernlackel ist ein Fleischberg mit Betonbirne und riesigen Schaufelhänden!\"  2. Dieser Provinzgorilla hat ‘nen Schädel wie ein Tresor und Pranken wie Radlader-Schaufeln!  3. Dieser Bauernschrank hat einen Betonkopf und zwei Gabelstapler statt Hände!"}]'::jsonb, ''),
  ('dea-quadraadlackl-is-einekumma-wiara-obelix-vaschnitt-auf-red-bull-mit-da-zoatn-eleganz-von-an-betonmischa', 'Dea Quadraadlackl is einekumma wiara Obelix-Vaschnitt auf Red Bull - mit da zoatn Eleganz von an Betonmischa!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der Quadratlackel ist reingekommen wie ein Obelix auf Red Bull - mit der zarten Eleganz von einem Betonmischer!', '[{"kategorie": "wörtlich", "text": "\"Der menschgewordene Presslufthammer ist reingetrampelt wie ein Obelix auf Adrenalin – so feinfühlig wie ein Betonmischer!\"  2. Der Quadratlackel betrat den Raum wie eine Lawine in Shorts – ein Obelix-Verschnitt auf Red Bull, mit der Feinmotorik eines Betonmischers!  3. Der Quadratlackel knallte rein wie ein Stier im Porzellanladen – mit dem Charme einer Abrissbirne und dem Taktgefühl eines Vorschlaghammers!"}]'::jsonb, ''),
  ('den-quadraadhiafla-heast-bei-uns-oom-im-easchdn-schdock-obwoi-a-si-im-koella-easchd-de-schuach-zuabind', 'Den Quadraadhiafla heast bei uns oom im easchdn Schdock, obwoi a si im Kölla easchd de Schuach zuabind!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Den Quadrathüfler hört man bei uns oben im ersten Stock, obwohl er sich im Keller erst die Schuhe zubindet!', '[{"kategorie": "wörtlich", "text": "\"Wenn sich der Zweihufbrummer unten im Keller die Schuhe zubindet, wackeln bei uns oben die Gläser im Schrank!\"  2. Wenn der zweibeinige Hufgaul unten im Keller nur mit den Zehen wackelt, denkt man oben im 1. Stock, die Erde tut sich auf!  3. Wenn die Abrissbirne unten schnauft, glauben wir oben, es ist ein kleines Erdbeben!"}]'::jsonb, ''),
  ('mit-so-an-hiinichn-lamuaschmaeae-kriagsd-de-oide-nie-ins-bett', 'Mit so an hiinichn Lamuaschmää kriagsd de Oide nie ins Bett!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Mit so einem kaputten Lamourschmäh kriegst du die Alte nie ins Bett!', '[{"kategorie": "wörtlich", "text": "\"Mit so einem plumpen Anmachspruch kriegst du die Alte nie ins Bett!\"  2. Mit deiner Flirtmasche kriegst du die Alte nicht mal bis zur Eingangstür - geschweige denn ins Bett!  3. Dein Liebesgeschwurbel bringt selbst Zimmerpalmen zum Welken!"}]'::jsonb, ''),
  ('neem-dem-langinus-kumm-i-ma-vua-wiara-goatnzweag-mit-mindaweatigkeitskomplex', 'Neem dem Langinus kumm I ma vua wiara Goatnzweag mit Mindaweatigkeitskomplex!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Neben diesem Langinus komm ich mir vor wie ein Gartenzwerg mit Minderwertigkeitskomplex!', '[{"kategorie": "wörtlich", "text": "\"Neben diesem langen Lulatsch komm ich mir vor wie ein Gartenzwerg mit Minderwertigkeitskomplex!\"  2. Wenn sich der Giraffenonkel neben mir streckt, brauch ich eine Drohne, um ihm ins Gesicht zu schauen!  3. Neben diesem \"Leuchtturm im Hemd\" schau ich aus wie der Einwurfschlitz von einem Wurlitzer!"}]'::jsonb, ''),
  ('longinus-woa-da-reemische-soidot-dea-in-leib-christi-mit-da-launzn-duachboad-hod-owa-des-liachtl-wos-daunn-aussegschdroid-is-woa-hoeoella-ois-de-sunn-iwa-golgata-und-hod-eam-de-blindheid-aus-da-soeoe-brennd', 'Longinus woa da reemische Soidot, dea in Leib Christi mit da Launzn duachboad hod - owa des Liachtl, wos daunn aussegschdroid is, woa höölla ois de Sunn iwa Golgata und hod eam de Blindheid aus da Söö brennd!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Longinus war der römische Soldat, der den Leib Christi mit der Lanze durchbohrt hat – doch das Licht, das dann rausgestrahlt ist, war heller als die Sonne über Golgatha und hat ihm die Blindheit aus der Seele gebrannt!', '[{"kategorie": "wörtlich", "text": "\"Longinus, der römische Soldat, stieß die Lanze in den Erlöser – doch was ihn traf, war kein Blut, sondern das Licht des Himmels, das ihm die Augen öffnete und das Herz entflammte!\"  2. Longinus durchbohrte das Fleisch des Gekreuzigten – und wurde vom Licht durchdrungen, das ihm die Dunkelheit aus Geist und Seele brannte!  3. Mit der Lanze traf er den Sohn Gottes – doch das Licht, das daraus strömte, traf Longinus tiefer als jede Klinge es je könnte!"}]'::jsonb, ''),
  ('neem-dem-longinus-schau-i-aus-wia-da-eiwuafschlitz-von-an-wualitza', 'Neem dem Longinus schau I aus wia da Eiwuafschlitz von an Wualitza!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Neben diesem Longinus schau ich aus wie der Einwurfschlitz von einem Wurlitzer!', '[{"kategorie": "wörtlich", "text": "\"Neben diesem ''Leuchtturm im Hemd'' schau ich aus wie der Einwurfschlitz von einem Wurlitzer!\"  2. Neben diesem langen Lulatsch komm ich mir vor wie ein Gartenzwerg mit Minderwertigkeitskomplex!  3. Wenn sich der Giraffenonkel neben mir streckt, brauch ich eine Drohne, um ihm ins Gesicht zu schauen!"}]'::jsonb, ''),
  ('mei-koella-is-voi-mit-lauta-fialefanz-den-kaa-sau-mea-brauchd', 'Mei Kölla is voi mit lauta Fialefanz, den kaa Sau mea brauchd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Mein Keller ist voll mit lauter Firlefanz, den keine Sau mehr braucht!', '[{"kategorie": "wörtlich", "text": "\"Mein Keller ist voll mit lauter Ramsch, den kein Mensch mehr braucht!\"  2. \"In meinem Keller stapelt sich nur [[Klumpert]], das seit Jahren keiner angerührt hat!\"  3. \"Alles da unten im Keller ist wertloses Zeug, das bloß Platz frisst!\""}]'::jsonb, ''),
  ('vagiss-den-fialefanz-und-moch-endlich-wos-gscheids', 'Vagiss den Fialefanz und moch endlich wos Gscheids!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Vergiss diesen Firlefanz und mach endlich was Gescheites!', '[{"kategorie": "wörtlich", "text": "\"Lass diese Spinnerei und mach endlich was Vernünftiges!\"  2. \"Hör auf mit dem albernen Herumgetue und mach was Ordentliches!\"  3. \"Vergiss diesen ''Gaga-Kram'' und tue endlich was Sinnvolles!\""}]'::jsonb, ''),
  ('des-is-nix-ois-larifari', 'Des is nix ois Larifari!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das ist nichts als Larifari!', '[{"kategorie": "wörtlich", "text": "\"Das ist nichts als sinnloses Gerede!\"  2. \"Das ist reines Blabla!\"  3. \"Das ist nichts als leeres Geschwätz!\""}]'::jsonb, ''),
  ('hea-auf-mit-dem-larifari-und-soog-endlich-wos-soch-is', 'Hea auf mit dem Larifari und soog endlich, wos Soch is!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Hör auf mit dem Larifari und sag endlich, was Sache ist!', '[{"kategorie": "wörtlich", "text": "\"Hör auf mit dem albernen Herumgetue und sag endlich, was Sache ist!\"  2. Spar dir den [[Firlefanz]] und komm endlich auf den Punkt!  3. Schluss mit dem ewigen Faxenmachen – was konkret ist gemeint?"}]'::jsonb, ''),
  ('de-oide-kaunnsd-vagessn-dera-haengan-de-lappaln-bis-zu-d-waadln', 'De Oide kaunnsd vagessn - dera hängan de Lappaln bis zu d''Waadln!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Die Alte kannst du vergessen - der hängen die Lapperln bis zu den Wadeln!', '[{"kategorie": "wörtlich", "text": "\"Die Alte kannst du vergessen - der hängen die Schamläppchen bis zu den Waden!\"  2. Die Alte kannst streichen – bei der schnalzen die Schamlippen im Takt der Schritte!  3. Ihre Schlabberlippen hängen tiefer runter als meine Wampe nach dem sechsten Bier!"}]'::jsonb, ''),
