  ('de-laeaetschadn-semmaen-kennds-eich-aum-oasch-pickn', 'De läätschadn Semmän kennds eich aum Oasch pickn!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Die lätscherten Semmeln könnt ihr euch auf den Arsch picken!', '[{"kategorie": "wörtlich", "text": "\"Die weichen Gummisemmeln könnt ihr euch auf den Hintern kleben!\"  2. Die Semmeln sind so weich und zäh – die pickst dir am besten auf den Hintern, dann hast einen Polster zum Sitzen!  3. Die Semmeln sind so pappig, die hätt ma gleich als Tapetenkleister verkaufen können!"}]'::jsonb, ''),
  ('dea-schlapfd-duach-de-geegnd-wiara-schloofwaundla', 'Dea schlapfd duach de Geegnd wiara Schloofwaundla!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der schlapft durch die Gegend wie ein Schlafwandler!', '[{"kategorie": "wörtlich", "text": "\"Der schlurft durch die Gegend wie ein Schlafwandler!\"  2. Der trottet durch die Gegend, als wär er nicht ganz wach!  3. Der schleift seine Beine nach, als wär er mit dem Kopf noch im Bett!"}]'::jsonb, ''),
  ('na-du-bist-ma-owa-a-lausa', 'Na du bist ma owa a Lausa!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Na du bist mir aber ein Lauser!', '[{"kategorie": "", "text": "Du bist mir aber ein Schlingel, ehrlich!  2. Was für ein Bengel bist denn du heut wieder!  3. Du kleiner Satansbraten, du!"}]'::jsonb, ''),
