  ('dea-hod-sejf-wiida-drei-wochn-gschdreebad-a-richtiga-tanuligam', 'Dea hod sejf wiida drei Wochn gschdreebad - a richtiga Tanuligam!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Der hat safe wieder drei Wochen gestrebert – ein richtiger Tanuligam!', '[{"kategorie": "wörtlich, Jugendsprache", "text": "\"Der hat sicher wieder drei Wochen durchgepaukt – kompletter Tanuligam, ehrlich!\"  2. Ich sag’s dir, der war wieder drei Wochen im Lernbunker – Tanuligam in Reinkultur!  3. Der tanzt wieder den Tanuligam – drei Wochen Bücher statt Leben!"}]'::jsonb, ''),
  ('i-bin-doo-da-baabo-tscheck-des-amoi', 'I bin doo da Baabo - tscheck des amoi!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Ich bin da der Babo - check das einmal!', '[{"kategorie": "wörtlich, Jugendsprache", "text": "\"Ich hab hier das Sagen - kapier das einmal!\"  2. Ich bin hier der Boss in dem Game – merk dir das!  3. Alles läuft hier über mich, Bruder – kein Film!"}]'::jsonb, ''),
